//! Replication: what a client needs from the server to keep a Replica of the board in step
//! (ADR 0017, decisions 4, 5 and 13; Task `ccc`, PR 2).
//!
//! Three things, and nothing of the Replica itself:
//!
//! * **Changed rows on each live event.** Triggers (migration 0111, generated by
//!   `scripts/generate-undo-triggers.sh change`) write one `change_log` row for every replicated row
//!   a write touched, undo, redo and cascades included, so no command has to remember to say what it
//!   changed. The server's publisher reads the log into each publication ([`drain`]) and deletes
//!   what it read in the same transaction: the log is a buffer, never a history, and a client that
//!   misses an event fetches a whole board.
//! * **A device snapshot** ([`snapshot`]): every replicated row, read in one transaction with the
//!   change-log position they stand at and the schema version, since `/backup` is the
//!   administrator's.
//! * **A board hash** ([`rules::hash`]) over those rows, kept up to date by the publisher
//!   ([`rules::SourceTracker`]) and computable by a Replica from its own copy ([`board_hash`]).
//!
//! The rules live in [`rules`] (pure); this module is the reads and writes that feed them.

pub mod model;
pub mod rules;
#[cfg(test)]
mod session_tests;
#[cfg(test)]
mod tests;

use sqlx::SqliteConnection;

use crate::{
    database::session::{Db, SessionFactory, SessionMode, Transactional},
    error::AppError,
};

pub use model::{RowChange, Snapshot, SourceDelta, SourceHead, StoredRow};
pub use rules::{is_replicated, SourceTracker, OMITTED_COLUMNS, UNREPLICATED_TABLES};

/// Reads and writes the change log and the replicated rows, on a session's connection.
///
/// Obtained as `db.replication()`; see [`Db`] for the borrow rules. Its methods are private: the
/// free functions of this module are the operations, because each needs a transaction to mean
/// anything.
pub struct ReplicationOperator<'session> {
    connection: &'session mut SqliteConnection,
}

impl<'session> ReplicationOperator<'session> {
    /// Wraps the connection a session is lending.
    pub(crate) fn new(connection: &'session mut SqliteConnection) -> Self {
        Self { connection }
    }

    async fn set_capture(&mut self, enabled: bool) -> Result<(), sqlx::Error> {
        sqlx::query("UPDATE change_capture SET enabled = ? WHERE id = 1")
            .bind(enabled)
            .execute(&mut *self.connection)
            .await?;
        Ok(())
    }

    async fn clear_log(&mut self) -> Result<(), sqlx::Error> {
        sqlx::query("DELETE FROM change_log")
            .execute(&mut *self.connection)
            .await?;
        Ok(())
    }

    async fn has_log(&mut self) -> Result<bool, sqlx::Error> {
        sqlx::query_scalar("SELECT EXISTS (SELECT 1 FROM change_log)")
            .fetch_one(&mut *self.connection)
            .await
    }

    /// The log, oldest first.
    async fn read_log(&mut self) -> Result<Vec<RowChange>, sqlx::Error> {
        let rows: Vec<(i64, String, i64, Option<String>)> =
            sqlx::query_as("SELECT seq, table_name, row_id, image FROM change_log ORDER BY seq")
                .fetch_all(&mut *self.connection)
                .await?;
        Ok(rows
            .into_iter()
            .map(|(seq, table, rowid, image)| RowChange {
                seq,
                table,
                rowid,
                image,
            })
            .collect())
    }

    /// Deletes the log up to and including `seq`.
    async fn delete_log_through(&mut self, seq: i64) -> Result<(), sqlx::Error> {
        sqlx::query("DELETE FROM change_log WHERE seq <= ?")
            .bind(seq)
            .execute(&mut *self.connection)
            .await?;
        Ok(())
    }

    /// The newest `seq` the log has ever assigned: `AUTOINCREMENT` keeps it after the rows are
    /// deleted, so it is the position of the rows whatever has been drained.
    async fn position(&mut self) -> Result<i64, sqlx::Error> {
        let seq: Option<i64> =
            sqlx::query_scalar("SELECT seq FROM sqlite_sequence WHERE name = 'change_log'")
                .fetch_optional(&mut *self.connection)
                .await?;
        Ok(seq.unwrap_or(0))
    }

    async fn schema_version(&mut self) -> Result<i64, sqlx::Error> {
        sqlx::query_scalar("SELECT COALESCE(MAX(version), 0) FROM _sqlx_migrations WHERE success")
            .fetch_one(&mut *self.connection)
            .await
    }

    /// Every replicated table, by name.
    async fn tables(&mut self) -> Result<Vec<String>, sqlx::Error> {
        let names: Vec<String> =
            sqlx::query_scalar("SELECT name FROM sqlite_master WHERE type = 'table' ORDER BY name")
                .fetch_all(&mut *self.connection)
                .await?;
        Ok(names
            .into_iter()
            .filter(|name| is_replicated(name))
            .collect())
    }

    /// The columns of `table` an image holds, in schema order.
    async fn image_columns(&mut self, table: &str) -> Result<Vec<String>, sqlx::Error> {
        let columns: Vec<String> =
            sqlx::query_scalar("SELECT name FROM pragma_table_info(?) ORDER BY cid")
                .bind(table)
                .fetch_all(&mut *self.connection)
                .await?;
        Ok(columns
            .into_iter()
            .filter(|column| !rules::is_omitted(table, column))
            .collect())
    }

    async fn rows_of(&mut self, table: &str) -> Result<Vec<StoredRow>, sqlx::Error> {
        let columns = self.image_columns(table).await?;
        let rows: Vec<(i64, String)> = sqlx::query_as(&row_query(table, &columns))
            .fetch_all(&mut *self.connection)
            .await?;
        Ok(rows
            .into_iter()
            .map(|(rowid, image)| StoredRow {
                table: table.to_owned(),
                rowid,
                image,
            })
            .collect())
    }

    async fn all_rows(&mut self) -> Result<Vec<StoredRow>, sqlx::Error> {
        let mut rows = Vec::new();
        for table in self.tables().await? {
            rows.extend(self.rows_of(&table).await?);
        }
        Ok(rows)
    }
}

/// The query that reads one table's rows as `(rowid, image)`, the image written the way the
/// change-log triggers write it: `json_object` over `columns` in schema order. A Replica reads its
/// own rows with this to compute the [board hash](rules::hash).
pub fn row_query(table: &str, columns: &[String]) -> String {
    let pairs = columns
        .iter()
        .map(|column| format!("'{column}', \"{column}\""))
        .collect::<Vec<_>>()
        .join(", ");
    format!("SELECT rowid, json_object({pairs}) FROM \"{table}\" ORDER BY rowid")
}

/// What a publisher starts from: the rows and where they stand, with the log emptied and capture
/// on, in one transaction, so that every write after this one is in the log and none before it is.
pub async fn start_capture(db: &mut Db<Transactional>) -> Result<SourceTracker, sqlx::Error> {
    let mut replication = db.replication();
    replication.clear_log().await?;
    replication.set_capture(true).await?;
    let upto = replication.position().await?;
    let rows = replication.all_rows().await?;
    Ok(SourceTracker::seed(&rows, upto))
}

/// Turns capture off and empties the log: for a host that does not publish rows (the desktop's
/// Standalone publisher), so the triggers cost nothing there and nothing piles up.
pub async fn stop_capture(db: &mut Db<Transactional>) -> Result<(), sqlx::Error> {
    let mut replication = db.replication();
    replication.set_capture(false).await?;
    replication.clear_log().await
}

/// Whether the log holds anything: a cheap look, so a publisher that finds nothing takes no writer
/// lock.
pub async fn has_logged<M: SessionMode>(db: &mut Db<M>) -> Result<bool, sqlx::Error> {
    db.replication().has_log().await
}

/// Takes the log: every entry written so far, oldest first, deleted from the log in the same
/// transaction. What the caller does not publish is gone, which is the point: a client that misses
/// a row fetches a whole board.
pub async fn drain(db: &mut Db<Transactional>) -> Result<Vec<RowChange>, sqlx::Error> {
    let mut replication = db.replication();
    let entries = replication.read_log().await?;
    if let Some(last) = entries.last() {
        replication.delete_log_through(last.seq).await?;
    }
    Ok(entries)
}

/// Every replicated row, the change-log position it stands at, its hash and the schema version,
/// read in one transaction (`db` is a read session: the rows and the position are one moment).
pub async fn snapshot(db: &mut Db<Transactional>) -> Result<Snapshot, sqlx::Error> {
    let mut replication = db.replication();
    let upto = replication.position().await?;
    let schema_version = replication.schema_version().await?;
    let rows = replication.all_rows().await?;
    Ok(Snapshot {
        upto,
        hash: rules::hash::board_hash(&rows),
        schema_version,
        rows,
    })
}

/// The board hash of the rows `db` holds, read as a snapshot is: what a Replica compares with the
/// server's.
pub async fn board_hash(db: &mut Db<Transactional>) -> Result<String, sqlx::Error> {
    Ok(rules::hash::board_hash(&db.replication().all_rows().await?))
}

/// The device snapshot as JSON, for the route that serves it: every replicated row read in one
/// transaction, with the run (`epoch`) and the `revision` it is at least at (read by the caller
/// before this runs, so a write that lands mid-read makes the snapshot look older than it is and
/// never newer). The body's shape is [`rules::wire::snapshot_body`].
pub async fn device_snapshot(
    factory: &SessionFactory,
    epoch: &str,
    revision: u64,
) -> Result<String, AppError> {
    let mut db = factory.begin_read().await?;
    let snapshot = snapshot(&mut db).await?;
    db.commit().await?;
    rules::wire::snapshot_body(&snapshot, epoch, revision)
        .map_err(|error| sqlx::Error::Protocol(error.to_string()).into())
}
